  function error(data) {
    if(data?.code==="ip_banned")return t(data.permanent===true?"Authentication blocked. Contact the administrator to restore access.":"Authentication temporarily blocked. Try again later.");
    if(data?.code==="invalid_security_policy")return t("Check the login security policy fields.");
    if(data?.code==="security_policy_conflict")return t("Login security policy changed. Reload it before saving again.");
    if(data?.code==="unknown_destination" || data?.code==="nonlocal_destination")return t("Choose an existing mailbox in this server's domain.");
    if(data?.code==="duplicate_forwarding")return t("This forwarding pattern already exists.");
    if(data?.code==="password_policy_violation")return t("Password does not meet the displayed requirements.");
    if(data?.code==="invalid_api_key")return data.field==="permissions" ? t("Choose valid API key permissions explicitly.") : t("Check the API key name or expiry and try again.");
    if(data?.code==="api_key_not_found")return t("The API key was not found. Refresh the key list.");
    if(data?.code==="api_key_limit")return t("The server's API key limit has been reached. Review existing keys or contact the server administrator.");
    if(data?.code==="administrator_required")return t("Administrator access is required.");
    if(data?.code==="password_policy_conflict")return t("The password policy changed. Reload it before saving again.");
    if(data?.code==="invalid_password_policy")return t("Check the password policy fields and try again.");
    if (acmeCodes[data?.code]) return t(acmeCodes[data.code]);
    if (setupCodes[data?.code]) return t(setupCodes[data.code]);
    const message = data?.error || "";
    if (Object.hasOwn(chinese, message)) return t(message);
    for (const [prefix, key, parameter] of [["Missing text field: ", "Missing text field: {field}", "field"], ["Field is too long: ", "Field is too long: {field}", "field"], ["A local recipient account does not exist: ", "A local recipient account does not exist: {recipient}", "recipient"]]) {
      if (message.startsWith(prefix)) return t(key, {[parameter]: message.slice(prefix.length)});
    }
    if (data?.code === "invalid_configuration" && data.field) return t("Check the configuration field: {field}.", {field:data.field});
    return t("The request failed. Please try again.");
  }
